import re


def title_of(html: str) -> str:
    """Return the text between <title> and </title> in an HTML string, or an empty string."""
    match = re.search(r"<title(?:\s+[^>]*)?>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
    if match is None:
        return ""
    return match.group(1)


def test_title_of_basic() -> None:
    html = "<html><head><title>My Title</title></head><body>Hello</body></html>"
    assert title_of(html) == "My Title"


def test_title_of_empty_title_tag() -> None:
    assert title_of("<title></title>") == ""


def test_title_of_missing_title() -> None:
    assert title_of("<html><head></head><body>No title here</body></html>") == ""


def test_title_of_case_insensitive() -> None:
    assert title_of("<TITLE>Uppercase</TITLE>") == "Uppercase"
    assert title_of("<Title>Mixed</title>") == "Mixed"


def test_title_of_with_attributes() -> None:
    assert title_of('<title lang="en">Localized Title</title>') == "Localized Title"


def test_title_of_multiline() -> None:
    html = "<title>\n  Line 1\n  Line 2\n</title>"
    assert title_of(html) == "\n  Line 1\n  Line 2\n"


def test_title_of_first_of_multiple() -> None:
    html = "<title>First</title><title>Second</title>"
    assert title_of(html) == "First"


def test_title_of_unclosed_or_malformed() -> None:
    assert title_of("<title>No closing tag") == ""
    assert title_of("Just closing</title>") == ""

